import {question,opportunity,surprise} from './events.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>'$'+Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2});
export function lessonHTML(r,lang='vi',reveal=true){if(!r)return '';const vi=lang==='vi',t=(a,b)=>vi?a:b;let insight='',tradeoff='',action='';
if(r.windfall){insight=t(`Bạn nhận ${cash(r.windfall)} từ một nguồn không phải lao động. Một khoản may mắn tăng vốn hiện tại nhưng không cải thiện khả năng tạo thu nhập lặp lại.`,`You received ${cash(r.windfall)} from a non-work source. A windfall increases today’s funds without improving recurring earning power.`);tradeoff=t('Nếu xem khoản thu bất thường là lương mới, bạn có thể tăng chi cố định rồi thiếu tiền khi tháng sau không còn khoản này. May mắn không phải một chiến lược có thể lặp lại.','Treating irregular receipts as a new salary can raise fixed spending and create a shortfall next month. Luck is not a repeatable strategy.');action=t('Tách riêng khoản thu một lần: xử lý nghĩa vụ, bù dự phòng rồi mới phân bổ cho mục tiêu dài hạn và tận hưởng. Không suy ra rằng nên chi tiền để săn may mắn.','Separate one-off money: cover obligations, rebuild reserves, then allocate to long-term goals and enjoyment. Do not infer that paying to chase luck is worthwhile.');}
else if(r.type==='opportunity'){const o=opportunity(r.eventId);insight=r.choice==='buy'?t(`Bạn đổi ${cash(r.bought)} tiền sẵn có lấy một khoản đầu tư. Mua tài sản chưa tạo ra lợi nhuận ngay; giá trị tương lai và khả năng bán mới quyết định kết quả.`,`You exchanged ${cash(r.bought)} of available cash for an investment. Buying does not create an immediate profit; future value and the ability to sell determine the outcome.`):t('Giữ tiền mặt bảo toàn quyền lựa chọn cho tháng sau. Bỏ qua một cơ hội không phải thất bại nếu khoản đầu tư khiến bạn thiếu tiền trả nghĩa vụ.','Keeping cash preserves next month’s choices. Passing is not a failure when investing would leave required bills unfunded.');tradeoff=t(`Tiền nằm trong tài sản không đồng nghĩa với tiền có thể rút ngay.${r.debtAdded?' Khoản nợ '+cash(r.debtAdded)+' vẫn phải trả ngay cả khi tài sản giảm giá.':''}`,`Asset value is not the same as immediately available cash.${r.debtAdded?' The '+cash(r.debtAdded)+' debt remains payable even if the asset loses value.':''}`);action=t('Trước khi mua, trừ sinh hoạt, kỳ trả góp và dự phòng khỏi tiền thanh khoản. Với tài sản khó bán, kiểm tra cả kịch bản thu nhập giảm; đừng chỉ nhìn lợi nhuận kỳ vọng.','Before buying, subtract living costs, installments and reserves from liquid funds. For illiquid assets, stress-test an income drop as well as expected returns.');}
else if(r.type==='expense'){const x=surprise(r.eventId);if(x?.optional){insight=r.choice==='spend'?t(`Bạn chọn trải nghiệm hoặc tiện ích, chi ${cash(r.optionalCost)}. Sự hài lòng có giá trị, nhưng khoản chi này giảm vốn phục vụ các mục tiêu khác.`,`You chose enjoyment or convenience and spent ${cash(r.optionalCost)}. Satisfaction has value, but the purchase reduces funds for other goals.`):t('Bạn trì hoãn một mong muốn để giữ tiền cho ưu tiên khác. Giá giảm không biến một món chưa cần thành khoản tiết kiệm.','You postponed a want to preserve money for other priorities. A discount does not turn an unnecessary purchase into savings.');tradeoff=t('Chi phí cơ hội gồm cả lợi nhuận bị bỏ lỡ và số tháng an toàn tài chính bị giảm. Tiêu dùng không xấu; tiêu dùng vượt khả năng mới làm kế hoạch mong manh.','Opportunity cost includes foregone returns and fewer months of financial safety. Consumption is not inherently bad; unaffordable consumption makes the plan fragile.');action=t('Tách ngân sách nhu cầu và mong muốn. Chờ 48 giờ, tính tổng chi phí sở hữu và chỉ mua nếu các nghĩa vụ cùng dự phòng vẫn được bảo vệ.','Separate needs from wants. Wait 48 hours, calculate total ownership costs and buy only if obligations and reserves remain protected.');}else{insight=t(`Hóa đơn ${cash(r.amount)} cho thấy vì sao dự phòng là vốn bảo vệ, không phải tiền nhàn rỗi.${r.sale?' Bạn đã phải bán '+cash(r.sale)+' tài sản để chi trả.':''}`,`The ${cash(r.amount)} bill shows why reserves are protection, not idle money.${r.sale?' You had to sell '+cash(r.sale)+' of assets to pay it.':''}`);tradeoff=t('Dự phòng thấp có thể buộc bán tài sản vào thời điểm bất lợi; tài sản ròng dương vẫn có thể đi cùng thiếu khả năng thanh toán.','Low reserves can force a sale at an unfavorable time; positive net worth can coexist with an inability to pay.');action=t('Ưu tiên bù lại dự phòng trước khi tăng rủi ro. Ước tính chi phí thiết yếu theo tháng, kiểm tra bảo hiểm phù hợp và dành khoản riêng cho sửa chữa định kỳ.','Rebuild reserves before increasing risk. Estimate essential monthly costs, review suitable insurance and budget separately for predictable maintenance.');}}
else if(r.type==='market'){insight=t(`Danh mục thay đổi ${cash(r.change)} theo mức phơi nhiễm thực tế. Kết quả một lần không chứng minh quyết định đầu tư ban đầu đúng hay sai.`,`Your portfolio changed by ${cash(r.change)} according to its actual exposures. One outcome does not prove the original investment decision right or wrong.`);tradeoff=t('Tiền mặt tránh biến động ngắn hạn nhưng bỏ lỡ một phần tăng trưởng. Đa dạng hóa giảm rủi ro tập trung, không loại bỏ rủi ro toàn thị trường.','Cash avoids short-term volatility but gives up some growth. Diversification reduces concentration risk, not market-wide risk.');action=t('Đánh giá tỷ trọng, thời hạn cần tiền và khả năng chịu lỗ. Tái cân bằng theo kế hoạch; đừng tăng cược chỉ vì vừa thắng hoặc bán hoảng loạn chỉ vì vừa giảm.','Review weights, time horizon and loss capacity. Rebalance to a plan; do not increase exposure merely after a win or panic-sell merely after a fall.');}
else if(r.type==='learn'){const q=question(r.questionId);insight=reveal&&q?q[lang][3]:t('Một câu trả lời chỉ có ý nghĩa khi bạn giải thích được dòng tiền và rủi ro phía sau. Trong trận nhiều người, đáp án không được tiết lộ trước lượt của đối thủ.','An answer matters when you can explain its cash-flow and risk consequences. Multiplayer answers are not disclosed ahead of opponents’ turns.');tradeoff=t('Biết khái niệm chưa đồng nghĩa thực hiện được khi chịu áp lực. Hãy phân biệt dữ kiện, giả định và điều chưa biết trước khi quyết định.','Knowing a concept does not guarantee using it under pressure. Separate facts, assumptions and unknowns before deciding.');action=t('Viết lại nguyên tắc bằng lời của bạn, nêu một trường hợp nguyên tắc không đủ và đặt một giới hạn cụ thể cho quyết định tiền bạc tiếp theo.','Restate the principle in your own words, identify a case where it is insufficient and set one concrete limit for your next money decision.');}
else{insight=t(`Khoản thu thêm ${cash(r.bonus)} tăng khả năng lựa chọn, nhưng không bảo đảm sẽ lặp lại. Đừng dùng thu nhập bất thường để tạo chi phí cố định lâu dài.`,`The extra ${cash(r.bonus)} increases your choices but may not recur. Avoid using irregular income to create permanent recurring expenses.`);tradeoff=t('Tiêu hết tạo niềm vui hôm nay; giữ toàn bộ cũng có chi phí cơ hội. Phân bổ theo mục tiêu giúp tránh nâng lối sống ngay khi có thêm tiền.','Spending everything brings enjoyment today; holding everything also has opportunity cost. Goal-based allocation helps prevent immediate lifestyle inflation.');action=t('Ưu tiên nghĩa vụ đến hạn, bù dự phòng, sau đó chia phần còn lại cho đầu tư và tận hưởng theo tỷ lệ đã định trước.','Prioritize due obligations, rebuild reserves, then split the remainder between investing and enjoyment using a pre-set allocation.');}
return `<section class="money-lesson"><h3>${t('Bài học từ quyết định','What this decision teaches')}</h3><p>${esc(insight)}</p><p><strong>${t('Đánh đổi:','Trade-off:')}</strong> ${esc(tradeoff)}</p><p><strong>${t('Mang vào đời sống:','Apply it:')}</strong> ${esc(action)}</p></section>`;}
export function tokenRoadmap(lang='vi'){return `<details class="token-roadmap"><summary>${lang==='vi'?'HUB là gì? Hiện tại & hướng phát triển':'What is HUB? Today & future direction'}</summary><p>${lang==='vi'?'HUB hiện là token giả lập trong Money Lab Hub, dùng ghi nhận thưởng và mức cam kết trong game. Không có giá trị tiền thật, chưa phát hành on-chain, không mua bán hoặc đổi sang OKB.':'HUB is currently a simulated token in Money Lab Hub for game rewards and commitments. It has no real-money value, is not issued on-chain and cannot be bought, sold or redeemed for OKB.'}</p><p>${lang==='vi'?'Định hướng phát triển: xây HUB thành token tiện ích có thể trao đổi trong Money Lab Hub, dùng mua quyền tham gia các chế độ chơi trả phí và dịch vụ trong hệ sinh thái. Mô hình dự kiến có thể yêu cầu mua HUB trước khi tham gia các chế độ đó. Đây là kế hoạch nghiên cứu, chưa mở bán, chưa có thị trường hay mức giá; không cam kết giá trị, thanh khoản hoặc lợi nhuận. Cơ chế token thật và thưởng thi đấu còn cần được thiết kế, đánh giá riêng trước khi triển khai.':'Future direction: develop HUB into a tradable utility token within Money Lab Hub, used to access paid game modes and ecosystem services. Those modes may require purchasing HUB before entry. This is a research roadmap: no sale, market or price exists, and value, liquidity or returns are not guaranteed. Real-token economics and competition rewards require separate design and evaluation before launch.'}</p></details>`;}
